create table if not exists public.applications(id bigint generated by default as identity primary key,name text not null,phone text not null,email text,course text not null,address text,message text,created_at timestamptz not null default now());alter table public.applications enable row level security;create policy "public can submit applications" on public.applications for insert to anon with check(true);create policy "no public reads" on public.applications for select to anon using(false);create index if not exists applications_created_at_idx on public.applications(created_at desc);